function showToast(message){const el=$("#toast");el.textContent=message;el.classList.add("show");clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove("show"),2800)}
function renderCircuits(filter="All"){
 const list=filter==="All"?circuits:circuits.filter(c=>c.region===filter);
 $("#circuitGrid").innerHTML=list.map((c)=>`<article class="circuit-card"><div class="circuit-visual" style="background:${c.gradient}"><span class="circuit-index">${String(circuits.indexOf(c)+1).padStart(2,"0")} / 10</span><span class="visual-icon">${c.icon}</span></div><div class="circuit-body"><span class="circuit-region">${c.region==="Ghats"?"GHATS & NATURE":c.region==="North"?"NORTH KARNATAKA":c.region==="Coast"?"KARAVALI": "HERITAGE & CULTURE"}</span><h3>${c.name}</h3><p>${c.desc}</p><div class="circuit-foot"><span>✦ ${c.places.length} suggested stops</span><div class="circuit-actions"><button data-choose="${c.id}">Plan route ↗</button><button data-language="${c.id}">Local phrases</button></div></div></div></article>`).join("");
 $$("#circuitGrid [data-choose]").forEach(btn=>btn.addEventListener("click",()=>{ $("#circuitSelect").value=btn.dataset.choose;applyDurationLimit(true);renderDialect(btn.dataset.choose);$("#planner").scrollIntoView({behavior:"smooth"});generate()}));
 $$("#circuitGrid [data-language]").forEach(btn=>btn.addEventListener("click",()=>{const key=btn.dataset.language;$("#circuitSelect").value=key;applyDurationLimit();renderDialect(key);$("#dialects").scrollIntoView({behavior:"smooth",block:"start"});}));
}
function applyDurationLimit(showMessage=false){
 const circuitSelect=$("#circuitSelect");
 const duration=$("#durationSelect");
 if(!circuitSelect || !duration) return {circuit:circuits[0], changed:false};
 const c=circuits.find(x=>x.id===circuitSelect.value)||circuits[0];
 const maxDays=Math.max(1,Math.min(Number(c.maxDays)||10,10));
 const previous=Number(duration.value)||3;
 const next=Math.min(previous,maxDays);
 const labels={1:"1 day · Quick escape",2:"2 days · Weekend",3:"3 days · Explorer",4:"4 days · Slow travel",5:"5 days · Deep dive",6:"6 days · Grand tour",7:"7 days · Full expedition"};
 // Rebuild options rather than relying on hidden/disabled <option> behaviour,
 // which differs between browsers and can leave an invalid duration selected.
 duration.replaceChildren(...Array.from({length:maxDays},(_,i)=>{
   const value=i+1, option=document.createElement("option");
   option.value=String(value); option.textContent=labels[value]; return option;
 }));
 duration.value=String(next);
 const changed=previous!==next;
 const hint=$("#durationHint");
 if(hint) hint.textContent=`${c.name}: choose 1–${maxDays} day${maxDays===1?"":"s"}. The planner only uses curated named places and will not repeat filler stops.`;
 if(showMessage && changed) showToast(`${c.name} supports up to ${maxDays} planned days here. Duration changed to ${next} day${next===1?"":"s"}.`);
 return {circuit:c, changed};
}
let hasGeneratedOnce=false;
function initSelect(){
 const circuitSelect=$("#circuitSelect");
 circuitSelect.innerHTML=circuits.map(c=>`<option value="${c.id}">${c.name}</option>`).join("");
 const dialectSelect=$("#dialectSelect");
 if(dialectSelect){dialectSelect.innerHTML=circuits.map(c=>`<option value="${c.id}">${c.name}</option>`).join("");dialectSelect.value=circuitSelect.value||"wildlife";dialectSelect.addEventListener("change",()=>{circuitSelect.value=dialectSelect.value;applyDurationLimit(true);renderDialect(dialectSelect.value);if(hasGeneratedOnce)generate();});}
 circuitSelect.value="wildlife";
 applyDurationLimit();
 circuitSelect.addEventListener("change",()=>{applyDurationLimit(true);renderDialect(circuitSelect.value);if(hasGeneratedOnce)generate();});
 $("#durationSelect").addEventListener("change",()=>{applyDurationLimit();if(hasGeneratedOnce)generate();});
}
function renderDialect(key,tab=activePhraseTab){
 const circuit=circuits.find(c=>c.id===key)||circuits.find(c=>c.id===(document.querySelector("#circuitSelect")?.value))||circuits[0];
 const profile=languageProfiles[circuit.id]||languageProfiles.wildlife;
 const regionSelect=$("#dialectSelect"); if(regionSelect && regionSelect.value!==circuit.id) regionSelect.value=circuit.id;
 activePhraseTab=phraseTabs.some(t=>t.key===tab)?tab:"people";
 const pill=$("#dialectPill"),description=$("#dialectDescription"),list=$("#phraseList");
 if(pill)pill.textContent=profile.title;
 if(description)description.textContent=profile.style;
 const tabs=$("#phraseTabs");
 if(tabs)tabs.innerHTML=phraseTabs.map(t=>`<button type="button" class="phrase-tab ${t.key===activePhraseTab?"active":""}" data-phrase-tab="${t.key}" aria-pressed="${t.key===activePhraseTab}">${t.icon} ${t.label}</button>`).join("");
 const phrases=profile.phrases[activePhraseTab]||profile.phrases.people;
 if(list)list.innerHTML=`<div class="phrase-context"><strong>${phraseTabs.find(t=>t.key===activePhraseTab)?.label||"Travel phrases"}</strong><span>Useful around ${profile.specialty}</span></div>`+phrases.map(p=>`<div class="phrase-item"><div><div class="phrase-category">${p[0]}</div><div class="phrase-kannada">${p[1]}</div><div class="phrase-roman">${p[2]}</div><div class="phrase-translation">“${p[3]}”</div></div><button type="button" class="speak-btn" data-speak="${encodeURIComponent(p[1])}">🔊 Speak</button></div>`).join("");
 $$("[data-phrase-tab]").forEach(b=>b.addEventListener("click",()=>renderDialect(circuit.id,b.dataset.phraseTab)));
 $$("[data-speak]").forEach(b=>b.addEventListener("click",()=>speak(decodeURIComponent(b.dataset.speak),"",b)));
}

let speechVoices=[];
function refreshSpeechVoices(){if(!('speechSynthesis' in window))return [];speechVoices=window.speechSynthesis.getVoices()||[];return speechVoices;}
if('speechSynthesis' in window){refreshSpeechVoices();window.speechSynthesis.addEventListener?.('voiceschanged',refreshSpeechVoices);}
function speak(kannadaText,romanText,button){
 if(!('speechSynthesis' in window)||!('SpeechSynthesisUtterance' in window)){showToast('Speech is not supported by this browser. Try the latest Chrome or Edge.');return;}
 const synth=window.speechSynthesis;const voices=refreshSpeechVoices();
 const knVoices=voices.filter(v=>/^kn(?:[-_]|$)/i.test(v.lang||''));
 const knVoice=knVoices.find(v=>/google|kannada/i.test(v.name||''))||knVoices.find(v=>v.default)||knVoices[0];
 if(!knVoice){showToast('No Kannada voice is available on this device. Install or enable Kannada speech in device settings, then reload Namma Trip.');return;}
 synth.cancel();if(button){button.disabled=true;button.textContent='🔊 Preparing…';}
 const utterance=new SpeechSynthesisUtterance(kannadaText);utterance.voice=knVoice;utterance.lang=knVoice.lang||'kn-IN';utterance.rate=0.78;utterance.pitch=1;utterance.volume=1;
 let finished=false;const reset=()=>{if(finished)return;finished=true;if(button){button.disabled=false;button.textContent='🔊 Speak';}};
 utterance.onstart=()=>{if(button)button.textContent='🔊 Speaking…';};utterance.onend=reset;utterance.onerror=e=>{reset();if(e.error!=='canceled'&&e.error!=='interrupted')showToast('Kannada speech failed. Try another Kannada voice in your device speech settings.');};
 setTimeout(()=>{try{synth.speak(utterance);}catch(e){reset();showToast('Could not start Kannada speech. Check device voice settings.');}},180);
}
