 if((interests||[]).some(v=>(vibeAliases[v]||v)==="Nature"))(natureNames[circuit.id]||[]).forEach(name=>extras.push({name,description:"Nature-focused stop. Check opening/access conditions and local safety guidance before travel.",category:"Nature · access-dependent",cost:0}));
