function plainText(value, fallback=""){
 if(value==null)return fallback;
 if(typeof value==="string"||typeof value==="number")return String(value);
 if(Array.isArray(value))return value.map(v=>plainText(v,"")).filter(Boolean).join(" · ")||fallback;
 if(typeof value==="object"){
  for(const key of ["name","title","label","place","text","value","display_name"]){
   if(value[key]!=null){const v=plainText(value[key],"");if(v&&v!=="[object Object]")return v;}
  }
 }
 return fallback;
}
