 const foods=(trip.foods||[]).map(f=>plainText(typeof f==="object"?f.name:f,"")).filter(Boolean).join(" · ");const chosenInterests=trip.interests||[];const stopText=trip.days_schedule.flatMap(d=>d.stops||[]).map(s=>(s.name||"")+" "+(s.category||"")).join(" ").toLowerCase();const interestPatterns={"UNESCO & Architecture":/heritage|architecture|history|temple|shrine|palace|fort|museum|market|church|monument|unesco|art/,"Ghats, Falls & Treks":/nature|waterfall|falls|trek|mountain|hill|river|lake|viewpoint|wildlife|forest|coast|beach|island|dam|cave/,"Native Cuisines & Oota":/food|meal|cuisine|dosa|rotti|pak|oota|tasting|darshini/,"Sacred Shrines & Mathas":/temple|shrine|matha|peetham|dargah|gurdwara|sacred|spiritual/,"Water Sports & Rafting":/rafting|river adventure|kayak|water sport|camp|safari/,"Silk, Sandalwood & Toys":/craft|silk|sandalwood|toy|handmade|shopping/};const interestLabels={"UNESCO & Architecture":"heritage","Ghats, Falls & Treks":"nature","Native Cuisines & Oota":"food","Sacred Shrines & Mathas":"shrines","Water Sports & Rafting":"adventure","Silk, Sandalwood & Toys":"crafts"};const missingLabels=chosenInterests.filter(v=>!interestPatterns[v]||!interestPatterns[v].test(stopText)).map(v=>interestLabels[v]||v);const interestNote=missingLabels.length?'<p class="selection-note">A little heads-up 💛: '+escapeHtml(missingLabels.join(", "))+' doesn’t have a strong match in this circuit for the selected days, so we’ve kept the plan focused on the closest relevant stops.</p>':"";const totalRange=trip.budget_breakdown?.trip_total_range||[trip.estimated_total_min??trip.estimated_total??0,trip.estimated_total_max??trip.estimated_total??0];const estMin=Number.isFinite(Number(trip.estimated_total_min))?Number(trip.estimated_total_min):(Number(totalRange[0])||0);const estMax=Number.isFinite(Number(trip.estimated_total_max))?Number(trip.estimated_total_max):(Number(totalRange[1])||estMin);
 $("#itineraryPanel").innerHTML=`<div class="trip-header"><div class="trip-header-top"><span class="trip-tag">YOUR KARUNADU ITINERARY</span><div class="trip-actions"><button id="saveTripBtn">♡ Save trip</button><button id="printTripBtn">↗ Print / PDF</button></div></div><h3>${escapeHtml(trip.circuit_name)}</h3><p>${escapeHtml(trip.description||c.desc)}</p><div class="trip-metrics"><div><span>PLANNED DURATION</span><strong>${trip.days} days · ${totalStops} stops</strong></div><div><span>EST. TRIP COST</span><strong>${money(estMin)}–${money(estMax)}</strong><small>Estimated per person</small></div><div><span>LIVE TRACKED TOTAL</span><strong id="trackedTotal">₹0</strong></div></div></div><div class="transit-note"><strong>↗ Transit recommendation:</strong> ${escapeHtml(trip.transit_recommendation||c.transit)}</div>${trip.route_plan?`<div class="transit-note"><strong>↗ Route continuity:</strong> ${escapeHtml(trip.route_plan.message||"Check the route before departure.")}${trip.route_plan.distance_km!=null?` <span>Calculated route distance (including day-to-day transfers): ${escapeHtml(String(trip.route_plan.distance_km))} km (not a live traffic estimate).</span>`:""}</div>`:""}${interestNote}<div class="timeline"><div class="timeline-title"><strong>Day-by-day master schedule</strong><span>Check stops to track activity spend</span></div>${trip.days_schedule.map(day=>`<section class="day-block"><div class="day-heading"><span class="day-badge">D${day.day}</span><div><strong>${escapeHtml(day.title)}</strong><small>Curated schedule · Day ${day.day}</small></div></div>${day.route_summary?`<div class="form-footnote"><strong>Road route:</strong> ${escapeHtml(String(day.route_summary.distance_km??0))} km · ${escapeHtml(String(day.route_summary.drive_minutes??0))} min estimated driving between this day’s stops.</div>`:""}${day.transfer_from_previous_day?`<div class="form-footnote"><strong>Transfer from previous day:</strong> ${escapeHtml(String(day.transfer_from_previous_day.distance_km))} km · ${escapeHtml(String(day.transfer_from_previous_day.drive_minutes))} min estimated driving. Plan the overnight stay and departure point.</div>`:""}${day.stops.map((s,i)=>{const id=`${day.day}-${i}`;return `<div class="stop" data-stop="${id}"><input type="checkbox" aria-label="Mark ${escapeHtml(s.name)} complete" data-cost="${Number(s.cost)||0}" data-stop-id="${id}"><div><span class="stop-time">${escapeHtml(s.time||["Morning","Afternoon","Evening"][i])}</span><span class="stop-name">${escapeHtml(s.name)}</span><div class="stop-desc">${escapeHtml(s.description||"Explore this regional highlight. Confirm current access details before travel.")}</div><div class="stop-meta">${escapeHtml(s.category||"Local experience")} · ${escapeHtml(stopFeeInfo(s).label)}</div></div><span class="stop-cost">${escapeHtml(stopFeeInfo(s).price)}</span></div>`}).join("")}${renderDayFoodBudget(trip,day)}</section>`).join("")}${renderBudgetBreakdown(trip)}<div class="trip-total"><span>Checked entry/activity spend</span><strong id="checkedCost">₹0</strong></div><div class="trip-total"><span>Regional food ideas</span><span>${escapeHtml(foods||"Ask locally for seasonal specialties")}</span></div>${(trip.notes||[]).map(n=>`<p class="form-footnote">• ${escapeHtml(n)}</p>`).join("")}</div>`;
 $$("[data-stop-id]").forEach(box=>box.addEventListener("change",()=>{const id=box.dataset.stopId;if(box.checked)checkedStops.add(id);else checkedStops.delete(id);box.closest(".stop").classList.toggle("done",box.checked);updateTracked()}));
