function updateTracked(){let total=0;$$("[data-stop-id]").forEach(b=>{if(b.checked)total+=Number(b.dataset.cost||0)});$("#checkedCost").textContent=money(total);$("#trackedTotal").textContent=money(total)}
function escapeHtml(value){return String(value??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}
function readPayload(){return {circuit:$("#circuitSelect").value,days:Number($("#durationSelect").value),style:$("#styleSelect").value,interests:$$(".interest input:checked").map(x=>x.value)}}
async function generate(payload=readPayload()){const limit=applyDurationLimit();payload={...payload,circuit:limit.circuit.id,days:Math.min(Number(payload.days)||1,limit.circuit.maxDays,Math.floor(limit.circuit.places.length/3))};hasGeneratedOnce=true;const btn=$("#generateBtn");btn.disabled=true;btn.innerHTML='<span class="spinner"></span> Building your itinerary…';$("#itineraryPanel").innerHTML='<div class="loading"><span class="spinner"></span> Curating your Karnataka journey…</div>';try{const trip=await requestItinerary(payload);renderTrip(trip);$("#itineraryPanel").scrollIntoView({behavior:"smooth",block:"nearest"})}catch(e){console.error(e);showToast("Could not generate itinerary. Please try again.");$("#itineraryPanel").innerHTML='<div class="empty-state"><h3>Let’s try that again.</h3><p>There was a problem creating the itinerary. Please check your selections and retry.</p></div>'}finally{btn.disabled=false;btn.innerHTML='Generate my itinerary <span>↗</span>'}}
function getSaved(){try{return JSON.parse(localStorage.getItem("nammaTripSaved")||"[]")}catch{return []}}
function refreshSavedCount(){$("#savedCount").textContent=getSaved().length}
function saveCurrentTrip(){if(!currentTrip){showToast("Generate an itinerary first.");return}const saved=getSaved();saved.unshift({...currentTrip,saved_at:new Date().toISOString()});localStorage.setItem("nammaTripSaved",JSON.stringify(saved.slice(0,20)));refreshSavedCount();showToast("Trip saved on this device.")}
function showSavedTrips(){const saved=getSaved();if(!saved.length){showToast("No saved trips yet. Generate and save a trip first.");return}const summary=saved.map((t,i)=>`${i+1}. ${t.circuit_name} · ${t.days} day(s) · ${money(t.estimated_total)}`).join("\n");const choice=prompt("Your saved trips:\n"+summary+"\n\nEnter a trip number to load it, or Cancel.");if(choice===null)return;const trip=saved[Number(choice)-1];if(trip){renderTrip(trip);$("#planner").scrollIntoView({behavior:"smooth"});}else showToast("That saved-trip number was not found.")}
$("#plannerForm").addEventListener("submit",e=>{e.preventDefault();generate()});
$("#circuitFilters").addEventListener("click",e=>{const b=e.target.closest("[data-filter]");if(!b)return;$$(".filter").forEach(x=>x.classList.toggle("active",x===b));renderCircuits(b.dataset.filter)});

$("#savedTripsBtn").addEventListener("click",showSavedTrips);
